  const resolved = resolveDirectory(root, directory);
  if (!resolved.ok) {
    throw new Error(resolved.message);
  }
  const dir = resolved.path;
  const empty = {
    kind: "author",
    present: false,
    directory: dir,
    name: path4.basename(dir),
    version: "",
    description: "",
    visibility: "",
    assets: [],
    built: []
  };
  let text2;
  try {
    text2 = await readFile2(path4.join(dir, FACET_JSON), "utf8");
  } catch (error51) {
    if (error51.code === "ENOENT") {
      return empty;
    }
    return { ...empty, present: true, problem: `${FACET_JSON} could not be read: ${error51.message}` };
  }
  let raw;
  try {
    raw = JSON.parse(text2);
  } catch (error51) {
    return { ...empty, present: true, problem: `${FACET_JSON} is not valid JSON: ${error51.message}` };
  }
  const parsed = FacetManifest.safeParse(raw);
  if (!parsed.success) {
    return { ...empty, present: true, problem: `${FACET_JSON} does not match the shape facet writes.` };
  }
