// mcp/src/capabilities.ts
import { existsSync as existsSync2 } from "node:fs";
import path5 from "node:path";
function readCapabilities(deps, root) {
  return {
    kind: "capabilities",
    tier: deps.supportsUi === true ? "apps" : "text",
    consoleAvailable: deps.supportsUi === true,
    rootsAdvertised: deps.clientCapabilities?.roots !== undefined,
    registryAvailable: true,
    projectRoot: root.path,
    rootVia: root.via,
    rootConfirmed: root.confirmed,
    projectFound: existsSync2(path5.join(root.path, "facets.json")),
    otherRoots: root.otherRoots
  };
}
function toText4(data) {
  const lines = [
    data.consoleAvailable ? "Console: available. This host renders MCP Apps, so facet tools open the panel and the user can act in it." : "Console: not available. This host did not negotiate MCP Apps, so prose is the only surface.",
    "Registry: available. Browsing, searching, and reading facets need no project — facet_browse and facet_detail work anywhere, and open the Registry screen."
  ];
  if (data.projectFound) {
    lines.push(`Project: ${data.projectRoot} (via ${data.rootVia}).`);
  } else {
    lines.push(`Project: none found at ${data.projectRoot} (via ${data.rootVia}).`, "That limits only the project-scoped tools — facet_list, facet_project, facet_add, facet_remove, facet_update. Everything else is unaffected.");
    if (!data.rootConfirmed) {
      lines.push("Nothing named a project, so that path is just the server's working directory. Pass `directory` or set FACET_PROJECT_ROOT to work against a real one.");
    }
  }
  if (data.otherRoots.length > 0) {
    lines.push(`Other folders the host has open: ${data.otherRoots.join(", ")}`);
  }
  return lines.join(`
`);
}
var capabilitiesShape = {};
var capabilitiesSchema = exports_external.object(capabilitiesShape);
function registerCapabilities(server, deps = {}) {
  const readRoot = rootReader(deps);
  const config2 = {
    title: "Host capabilities",
    description: "Report what this host negotiated and where the project root came from: whether an interactive console can be opened, and whether a project was actually found. Call this before answering a facet request when the surface matters.",
    inputSchema: capabilitiesShape,
    annotations: { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false }
  };
  const handler = async (rawArgs) => {
    capabilitiesSchema.parse(rawArgs ?? {});
    const data = readCapabilities(deps, readRoot());
    return {
      content: [{ type: "text", text: toText4(data) }],
      structuredContent: data
    };
  };
  server.registerTool("facet_capabilities", config2, handler);
}

